     1→import { describe, expect, test } from "bun:test";
     2→import { createTelemetryConfig, recordLlmMetrics, recordLlmError } from "../../../app/src/server/telemetry/ai-telemetry";
     3→import { FUNCTION_IDS } from "../../../app/src/server/telemetry/function-ids";
     4→
     5→describe("createTelemetryConfig", () => {
     6→  test("returns enabled telemetry config with functionId and service metadata", () => {
     7→    const config = createTelemetryConfig(FUNCTION_IDS.EXTRACTION);
     8→
     9→    expect(config).toEqual({
    10→      isEnabled: true,
    11→      functionId: "osabio.extraction",
    12→      metadata: { service: "osabio-server" },
    13→    });
    14→  });
    15→
    16→  test("returns correct functionId for each taxonomy entry", () => {
    17→    for (const [, functionId] of Object.entries(FUNCTION_IDS)) {
    18→      const config = createTelemetryConfig(functionId);
    19→      expect(config.functionId).toBe(functionId);
    20→      expect(config.isEnabled).toBe(true);
    21→      expect(config.metadata).toEqual({ service: "osabio-server" });
    22→    }
    23→  });
    24→});
    25→
    26→describe("recordLlmMetrics", () => {
    27→  test("records metrics without throwing when called with valid usage", () => {
    28→    // Should not throw - metrics are no-ops when no MeterProvider is registered
    29→    expect(() => {
    30→      recordLlmMetrics(FUNCTION_IDS.CHAT_AGENT, { promptTokens: 100, completionTokens: 50 }, 1234);
    31→    }).not.toThrow();
    32→  });
    33→
    34→  test("handles zero values gracefully", () => {
    35→    expect(() => {
    36→      recordLlmMetrics(FUNCTION_IDS.EXTRACTION, { promptTokens: 0, completionTokens: 0 }, 0);
    37→    }).not.toThrow();
    38→  });
    39→
    40→  test("handles undefined token counts gracefully", () => {
    41→    expect(() => {
    42→      recordLlmMetrics(FUNCTION_IDS.PM_AGENT, {}, 500);
    43→    }).not.toThrow();
    44→  });
    45→});
    46→
    47→describe("recordLlmError", () => {
    48→  test("increments error counter without throwing", () => {
    49→    expect(() => {
    50→      recordLlmError(FUNCTION_IDS.OBSERVER_VERIFICATION, "timeout");
    51→    }).not.toThrow();
    52→  });
    53→
    54→  test("accepts any error type string", () => {
    55→    expect(() => {
    56→      recordLlmError(FUNCTION_IDS.BEHAVIOR_SCORER, "rate_limit");
    57→      recordLlmError(FUNCTION_IDS.INTENT_AUTHORIZER, "invalid_output");
    58→      recordLlmError(FUNCTION_IDS.ONBOARDING, "network_error");
    59→    }).not.toThrow();
    60→  });
    61→});
