     1→/**
     2→ * Milestone 2: Policy Creation + Validation
     3→ *
     4→ * Traces: US-PCUI-02 (Create Policy)
     5→ *
     6→ * Validates that human identities can create draft policies with valid
     7→ * rules, and that creation is rejected for missing title, missing rules,
     8→ * and invalid predicate structure.
     9→ *
    10→ * Driving ports:
    11→ *   POST /api/workspaces/:wsId/policies
    12→ *   GET  /api/workspaces/:wsId/policies/:id
    13→ */
    14→import { describe, expect, it } from "bun:test";
    15→import {
    16→  setupAcceptanceSuite,
    17→  createTestUser,
    18→  createTestWorkspace,
    19→  createTestIdentity,
    20→  createPolicyViaApi,
    21→  getPolicyDetail,
    22→  buildPolicyBody,
    23→  DEFAULT_REGO_SOURCE,
    24→  type PolicyDetailResponse,
    25→} from "./policy-crud-test-kit";
    26→
    27→const getRuntime = setupAcceptanceSuite("policy_crud_m2_creation");
    28→
    29→// =============================================================================
    30→// US-PCUI-02: Create Policy
    31→// =============================================================================
    32→
    33→describe("Milestone 2: Policy Creation (US-PCUI-02)", () => {
    34→
    35→  // ---------------------------------------------------------------------------
    36→  // Walking Skeleton: Admin creates a draft policy with valid rules
    37→  // AC: POST returns 201 with policy_id, policy has draft status and version 1
    38→  // ---------------------------------------------------------------------------
    39→  it("admin creates a draft policy with one deny rule", async () => {
    40→    const { baseUrl, surreal } = getRuntime();
    41→
    42→    // Given an admin in a workspace
    43→    const user = await createTestUser(baseUrl, "m2-create-happy");
    44→    const workspace = await createTestWorkspace(baseUrl, user);
    45→
    46→    // When admin creates a policy with Rego source
    47→    const response = await createPolicyViaApi(
    48→      baseUrl,
    49→      user.headers,
    50→      workspace.workspaceId,
    51→      buildPolicyBody({
    52→        title: "Block Production Deployments",
    53→        description: "Prevents agents from deploying to production without human approval",
    54→        rego_source: DEFAULT_REGO_SOURCE,
    55→        human_veto_required: true,
    56→      }),
    57→    );
    58→
    59→    // Then the policy is created as a draft
    60→    expect(response.status).toBe(201);
    61→    const body = await response.json() as { policy_id: string };
    62→    expect(body.policy_id).toBeDefined();
    63→
    64→    // And the policy detail shows draft status with version 1
    65→    const detailResponse = await getPolicyDetail(
    66→      baseUrl, user.headers, workspace.workspaceId, body.policy_id,
    67→    );
    68→    expect(detailResponse.status).toBe(200);
    69→    const detail = await detailResponse.json() as PolicyDetailResponse;
    70→    expect(detail.policy.status).toBe("draft");
    71→    expect(detail.policy.version).toBe(1);
    72→    expect(detail.policy.title).toBe("Block Production Deployments");
    73→    expect(detail.policy.human_veto_required).toBe(true);
    74→  }, 120_000);
    75→
    76→  // ---------------------------------------------------------------------------
    77→  // Admin creates policy with multiple rules
    78→  // AC: Policy with multiple rules is created and all rules persisted
    79→  // ---------------------------------------------------------------------------
    80→  it("admin creates a policy with multiple rules at different priorities", async () => {
    81→    const { baseUrl } = getRuntime();
    82→
    83→    // Given an admin in a workspace
    84→    const user = await createTestUser(baseUrl, "m2-multi-rules");
    85→    const workspace = await createTestWorkspace(baseUrl, user);
    86→
    87→    // When admin creates a policy with Rego source containing multiple rules
    88→    const multiRuleRego = `package osabio.policy
    89→default allow = false
    90→allow { input.action_spec.action == "read" }
    91→deny { input.action_spec.action == "deploy" }`;
    92→
    93→    const response = await createPolicyViaApi(
    94→      baseUrl,
    95→      user.headers,
    96→      workspace.workspaceId,
    97→      buildPolicyBody({
    98→        title: "Tiered Access Control",
    99→        rego_source: multiRuleRego,
   100→      }),
   101→    );
   102→
   103→    // Then the policy is created successfully
   104→    expect(response.status).toBe(201);
   105→    const body = await response.json() as { policy_id: string };
   106→
   107→    const detailResponse = await getPolicyDetail(
   108→      baseUrl, user.headers, workspace.workspaceId, body.policy_id,
   109→    );
   110→    const detail = await detailResponse.json() as PolicyDetailResponse;
   111→    expect(detail.policy.title).toBe("Tiered Access Control");
   112→  }, 120_000);
   113→
   114→  // ---------------------------------------------------------------------------
   115→  // Policy with selector is created correctly
   116→  // AC: Selector fields are persisted
   117→  // ---------------------------------------------------------------------------
   118→  it("admin creates a policy with agent role selector", async () => {
   119→    const { baseUrl } = getRuntime();
   120→
   121→    // Given an admin in a workspace
   122→    const user = await createTestUser(baseUrl, "m2-selector");
   123→    const workspace = await createTestWorkspace(baseUrl, user);
   124→
   125→    // When admin creates a policy with a selector
   126→    const response = await createPolicyViaApi(
   127→      baseUrl,
   128→      user.headers,
   129→      workspace.workspaceId,
   130→      buildPolicyBody({
   131→        title: "Coding Agent Budget Cap",
   132→        selector: { agent_role: "coding" },
   133→        rego_source: DEFAULT_REGO_SOURCE,
   134→      }),
   135→    );
   136→
   137→    // Then the selector is preserved on the created policy
   138→    expect(response.status).toBe(201);
   139→    const body = await response.json() as { policy_id: string };
   140→
   141→    const detailResponse = await getPolicyDetail(
   142→      baseUrl, user.headers, workspace.workspaceId, body.policy_id,
   143→    );
   144→    const detail = await detailResponse.json() as PolicyDetailResponse;
   145→    expect(detail.policy.selector.agent_role).toBe("coding");
   146→  }, 120_000);
   147→});
   148→
   149→// =============================================================================
   150→// US-PCUI-02: Validation Errors
   151→// =============================================================================
   152→
   153→describe("Milestone 2: Policy Creation Validation (US-PCUI-02)", () => {
   154→
   155→  // ---------------------------------------------------------------------------
   156→  // Missing title is rejected
   157→  // AC: POST without title returns 400
   158→  // ---------------------------------------------------------------------------
   159→  it("policy creation is rejected without a title", async () => {
   160→    const { baseUrl } = getRuntime();
   161→
   162→    // Given an admin in a workspace
   163→    const user = await createTestUser(baseUrl, "m2-no-title");
   164→    const workspace = await createTestWorkspace(baseUrl, user);
   165→
   166→    // When admin attempts to create a policy without a title
   167→    const response = await createPolicyViaApi(
   168→      baseUrl,
   169→      user.headers,
   170→      workspace.workspaceId,
   171→      {
   172→        title: "",
   173→        description: "Missing title test",
   174→        rego_source: DEFAULT_REGO_SOURCE,
   175→      } as any,
   176→    );
   177→
   178→    // Then the request is rejected with validation error
   179→    expect(response.status).toBe(400);
   180→    const body = await response.json() as { error: string };
   181→    expect(body.error).toContain("title");
   182→  }, 120_000);
   183→
   184→  // ---------------------------------------------------------------------------
   185→  // Missing rego_source is rejected
   186→  // AC: POST without rego_source returns 400
   187→  // ---------------------------------------------------------------------------
   188→  it("policy creation is rejected without rego_source", async () => {
   189→    const { baseUrl } = getRuntime();
   190→
   191→    // Given an admin in a workspace
   192→    const user = await createTestUser(baseUrl, "m2-no-rego");
   193→    const workspace = await createTestWorkspace(baseUrl, user);
   194→
   195→    // When admin attempts to create a policy without rego_source
   196→    const response = await createPolicyViaApi(
   197→      baseUrl,
   198→      user.headers,
   199→      workspace.workspaceId,
   200→      {
   201→        title: "No Rego Policy",
   202→        description: "Policy with no rego_source for testing",
   203→      } as any,
   204→    );
   205→
   206→    // Then the request is rejected with validation error
   207→    expect(response.status).toBe(400);
   208→    const body = await response.json() as { error: string };
   209→    expect(body.error).toContain("rego_source");
   210→  }, 120_000);
   211→
   212→  // ---------------------------------------------------------------------------
   213→  // Invalid Rego syntax is rejected
   214→  // AC: POST with malformed Rego source returns 400
   215→  // ---------------------------------------------------------------------------
   216→  it("policy creation is rejected with invalid Rego syntax", async () => {
   217→    const { baseUrl } = getRuntime();
   218→
   219→    // Given an admin in a workspace
   220→    const user = await createTestUser(baseUrl, "m2-bad-rego");
   221→    const workspace = await createTestWorkspace(baseUrl, user);
   222→
   223→    // When admin attempts to create a policy with invalid Rego
   224→    const response = await createPolicyViaApi(
   225→      baseUrl,
   226→      user.headers,
   227→      workspace.workspaceId,
   228→      {
   229→        title: "Bad Rego Policy",
   230→        description: "Policy with invalid Rego syntax",
   231→        rego_source: "package osabio.policy\nthis is not valid rego {{{}}}",
   232→      } as any,
   233→    );
   234→
   235→    // Then the request is rejected with validation error
   236→    expect(response.status).toBe(400);
   237→  }, 120_000);
   238→
   239→  // ---------------------------------------------------------------------------
   240→  // Missing package declaration is rejected
   241→  // AC: POST with Rego missing required package returns 400
   242→  // ---------------------------------------------------------------------------
   243→  it("policy creation is rejected without required package declaration", async () => {
   244→    const { baseUrl } = getRuntime();
   245→
   246→    // Given an admin in a workspace
   247→    const user = await createTestUser(baseUrl, "m2-no-package");
   248→    const workspace = await createTestWorkspace(baseUrl, user);
   249→
   250→    // When admin attempts to create a policy without the required package
   251→    const response = await createPolicyViaApi(
   252→      baseUrl,
   253→      user.headers,
   254→      workspace.workspaceId,
   255→      {
   256→        title: "Missing Package Policy",
   257→        description: "Policy without osabio.policy package",
   258→        rego_source: "package wrong.package\ndefault allow = true",
   259→      } as any,
   260→    );
   261→
   262→    // Then the request is rejected
   263→    expect(response.status).toBe(400);
   264→  }, 120_000);
   265→});
