     1→import { afterAll, beforeAll, describe, expect, it } from "bun:test";
     2→import { randomUUID } from "node:crypto";
     3→import { RecordId, Surreal } from "surrealdb";
     4→import { applyTestSchema } from "../acceptance-test-kit";
     5→import {
     6→  getProjectGraphView,
     7→  getWorkspaceGraphOverview,
     8→  getFocusedGraphView,
     9→  type GraphEntityRecord,
    10→} from "../../../app/src/server/graph/queries";
    11→
    12→/**
    13→ * Acceptance tests for governance visualization in graph views.
    14→ *
    15→ * Covers:
    16→ * - AC-1.1..AC-1.4: Policy nodes with status filtering
    17→ * - AC-2.1..AC-2.4, AC-2.8: Intent nodes with status filtering + focused view
    18→ * - AC-4.1..AC-4.4: Governance edge classification
    19→ * - AC-X.4: Existing graph nodes continue to appear correctly
    20→ */
    21→
    22→const surrealUrl = process.env.SURREAL_URL ?? "ws://127.0.0.1:8000/rpc";
    23→const surrealUsername = process.env.SURREAL_USERNAME ?? "root";
    24→const surrealPassword = process.env.SURREAL_PASSWORD ?? "root";
    25→
    26→let surreal: Surreal;
    27→let namespace: string;
    28→let database: string;
    29→
    30→let workspaceRecord: RecordId<"workspace", string>;
    31→let projectRecord: RecordId<"project", string>;
    32→let taskRecord: RecordId<"task", string>;
    33→let identityRecord: RecordId<"identity", string>;
    34→
    35→// Policy records
    36→let activePolicyRecord: RecordId<"policy", string>;
    37→let testingPolicyRecord: RecordId<"policy", string>;
    38→let draftPolicyRecord: RecordId<"policy", string>;
    39→let deprecatedPolicyRecord: RecordId<"policy", string>;
    40→let supersededPolicyRecord: RecordId<"policy", string>;
    41→
    42→// Intent records
    43→let executingIntentRecord: RecordId<"intent", string>;
    44→let pendingVetoIntentRecord: RecordId<"intent", string>;
    45→let completedIntentRecord: RecordId<"intent", string>;
    46→let vetoedIntentRecord: RecordId<"intent", string>;
    47→let failedIntentRecord: RecordId<"intent", string>;
    48→
    49→// Agent session for gates edge
    50→let agentSessionRecord: RecordId<"agent_session", string>;
    51→
    52→// Learning and git_commit records
    53→let learningRecord: RecordId<"learning", string>;
    54→let gitCommitRecord: RecordId<"git_commit", string>;
    55→
    56→beforeAll(async () => {
    57→  const runId = `${Date.now()}_${Math.floor(Math.random() * 100000)}`;
    58→  namespace = `smoke_gov_viz_${runId}`;
    59→  database = `gov_viz_${Math.floor(Math.random() * 100000)}`;
    60→
    61→  surreal = new Surreal();
    62→  await surreal.connect(surrealUrl);
    63→  await surreal.signin({ username: surrealUsername, password: surrealPassword });
    64→  await surreal.query(`DEFINE NAMESPACE ${namespace};`);
    65→  await surreal.use({ namespace });
    66→  await surreal.query(`DEFINE DATABASE ${database};`);
    67→  await surreal.use({ namespace, database });
    68→
    69→  await applyTestSchema(surreal);
    70→
    71→  const now = new Date();
    72→
    73→  // ── Workspace ──
    74→  workspaceRecord = new RecordId("workspace", randomUUID());
    75→  await surreal.create(workspaceRecord).content({
    76→    name: "Governance Viz Workspace",
    77→    status: "active",
    78→    onboarding_complete: true,
    79→    onboarding_turn_count: 0,
    80→    onboarding_summary_pending: false,
    81→    onboarding_started_at: now,
    82→    created_at: now,
    83→  });
    84→
    85→  // ── Identity ──
    86→  identityRecord = new RecordId("identity", randomUUID());
    87→  await surreal.query("CREATE $record CONTENT $content;", {
    88→    record: identityRecord,
    89→    content: { name: "Admin User", type: "human", workspace: workspaceRecord, created_at: now },
    90→  });
    91→  await surreal.query("RELATE $identity->member_of->$workspace SET added_at = $now;", {
    92→    identity: identityRecord,
    93→    workspace: workspaceRecord,
    94→    now,
    95→  });
    96→
    97→  // ── Project + Task ──
    98→  projectRecord = new RecordId("project", randomUUID());
    99→  await surreal.query("CREATE $record CONTENT $content;", {
   100→    record: projectRecord,
   101→    content: { name: "Gov Project", status: "active", workspace: workspaceRecord, created_at: now, updated_at: now },
   102→  });
   103→  await surreal.query("RELATE $workspace->has_project->$project SET added_at = $now;", {
   104→    workspace: workspaceRecord,
   105→    project: projectRecord,
   106→    now,
   107→  });
   108→
   109→  taskRecord = new RecordId("task", randomUUID());
   110→  await surreal.query("CREATE $record CONTENT $content;", {
   111→    record: taskRecord,
   112→    content: { title: "Deploy staging", status: "open", workspace: workspaceRecord, created_at: now, updated_at: now },
   113→  });
   114→  await surreal.query("RELATE $task->belongs_to->$project SET added_at = $now;", {
   115→    task: taskRecord,
   116→    project: projectRecord,
   117→    now,
   118→  });
   119→
   120→  // ── Agent session (for gates edge) ──
   121→  agentSessionRecord = new RecordId("agent_session", randomUUID());
   122→  await surreal.query("CREATE $record CONTENT $content;", {
   123→    record: agentSessionRecord,
   124→    content: {
   125→      agent: "test-agent",
   126→      orchestrator_status: "active",
   127→      workspace: workspaceRecord,
   128→      started_at: now,
   129→      created_at: now,
   130→    },
   131→  });
   132→
   133→  // ── Policies (5 statuses) ──
   134→  const policyBase = {
   135→    version: 1,
   136→    selector: {},
   137→    rules: [{ id: "r1", condition: { field: "action", operator: "eq", value: "deploy" }, effect: "deny", priority: 100 }],
   138→    rego_source: "package osabio.policy\ndefault allow = true",
   139→    human_veto_required: false,
   140→    created_by: identityRecord,
   141→    workspace: workspaceRecord,
   142→    created_at: now,
   143→  };
   144→
   145→  activePolicyRecord = new RecordId("policy", randomUUID());
   146→  await surreal.query("CREATE $record CONTENT $content;", {
   147→    record: activePolicyRecord,
   148→    content: { ...policyBase, title: "Active Budget Guard", status: "active" },
   149→  });
   150→
   151→  testingPolicyRecord = new RecordId("policy", randomUUID());
   152→  await surreal.query("CREATE $record CONTENT $content;", {
   153→    record: testingPolicyRecord,
   154→    content: { ...policyBase, title: "Testing Rate Limiter", status: "testing" },
   155→  });
   156→
   157→  draftPolicyRecord = new RecordId("policy", randomUUID());
   158→  await surreal.query("CREATE $record CONTENT $content;", {
   159→    record: draftPolicyRecord,
   160→    content: { ...policyBase, title: "Draft Policy", status: "draft" },
   161→  });
   162→
   163→  deprecatedPolicyRecord = new RecordId("policy", randomUUID());
   164→  await surreal.query("CREATE $record CONTENT $content;", {
   165→    record: deprecatedPolicyRecord,
   166→    content: { ...policyBase, title: "Deprecated Policy", status: "deprecated" },
   167→  });
   168→
   169→  supersededPolicyRecord = new RecordId("policy", randomUUID());
   170→  await surreal.query("CREATE $record CONTENT $content;", {
   171→    record: supersededPolicyRecord,
   172→    content: { ...policyBase, title: "Superseded Policy", status: "superseded" },
   173→  });
   174→
   175→  // ── Governance edges (only for active + testing) ──
   176→  await surreal.query("RELATE $identity->governing->$policy SET created_at = $now;", {
   177→    identity: identityRecord,
   178→    policy: activePolicyRecord,
   179→    now,
   180→  });
   181→  await surreal.query("RELATE $policy->protects->$workspace SET created_at = $now;", {
   182→    policy: activePolicyRecord,
   183→    workspace: workspaceRecord,
   184→    now,
   185→  });
   186→  await surreal.query("RELATE $identity->governing->$policy SET created_at = $now;", {
   187→    identity: identityRecord,
   188→    policy: testingPolicyRecord,
   189→    now,
   190→  });
   191→  await surreal.query("RELATE $policy->protects->$workspace SET created_at = $now;", {
   192→    policy: testingPolicyRecord,
   193→    workspace: workspaceRecord,
   194→    now,
   195→  });
   196→
   197→  // ── Learning ──
   198→  learningRecord = new RecordId("learning", randomUUID());
   199→  await surreal.query("CREATE $record CONTENT $content;", {
   200→    record: learningRecord,
   201→    content: {
   202→      text: "Customs clearance requires advance filing 72 hours before arrival",
   203→      learning_type: "constraint",
   204→      status: "active",
   205→      source: "human",
   206→      priority: "medium",
   207→      target_agents: ["logistics-agent"],
   208→      workspace: workspaceRecord,
   209→      created_at: now,
   210→      updated_at: now,
   211→    },
   212→  });
   213→
   214→  // ── Git Commit ──
   215→  gitCommitRecord = new RecordId("git_commit", randomUUID());
   216→  await surreal.query("CREATE $record CONTENT $content;", {
   217→    record: gitCommitRecord,
   218→    content: {
   219→      sha: "abc123def456789012345678901234567890abcd",
   220→      message: "fix(logistics): correct duty calculation for cross-border shipments",
   221→      author_name: "logistics-dev",
   222→      repository: "supply-chain/logistics-engine",
   223→      workspace: workspaceRecord,
   224→      created_at: now,
   225→    },
   226→  });
   227→
   228→  // ── Intents (5 statuses) ──
   229→  const intentBase = {
   230→    reasoning: "test reasoning",
   231→    priority: 50,
   232→    action_spec: { provider: "test", action: "deploy", params: {} },
   233→    requester: identityRecord,
   234→    workspace: workspaceRecord,
   235→    created_at: now,
   236→  };
   237→
   238→  const traceRecord = new RecordId("trace", randomUUID());
   239→  await surreal.query("CREATE $record CONTENT $content;", {
   240→    record: traceRecord,
   241→    content: { type: "intent_submission", actor: identityRecord, workspace: workspaceRecord, created_at: now },
   242→  });
