    41→  it("near-duplicate learning detected when texts are semantically identical", async () => {
    42→    const { baseUrl, surreal } = getRuntime();
    43→
    44→    // Given a workspace with an active learning about null usage
    45→    const { workspaceId } = await createTestWorkspace(surreal, "near-dup");
    46→    await createTestLearning(surreal, workspaceId, {
