    63→    const duplicates = body.collisions.filter(
    64→      (c: { collisionType: string }) => c.collisionType === "duplicates",
    65→    );
    66→    expect(duplicates.length).toBeGreaterThanOrEqual(1);
    67→    // BM25 scores are not normalized 0-1 (unlike cosine similarity).
