     4→ * Validates that the Authorizer reads dynamic behavior scores from
     5→ * behavior records with arbitrary metric_type values, and enforces
     6→ * Rego policy thresholds to approve or deny agent intents.
     7→ *
     8→ * Driving ports:
     9→ *   enrichBehaviorScores (context enrichment function)
    10→ *   evaluateRegoPolicy (Rego policy evaluation)
    11→ *   SurrealDB direct queries (seeding + verification)
    12→ */
    13→import { describe, expect, it } from "bun:test";
    14→import {
    15→  setupDynamicBehaviorsSuite,
    16→  setupBehaviorWorkspace,
    17→  createAgentIdentity,
    18→  createBehaviorDefinition,
    19→  createScoredBehaviorRecord,
    20→  createBehaviorPolicy,
    21→  getLatestBehaviorScore,
    22→} from "./dynamic-behaviors-test-kit";
    23→import type { IntentEvaluationContext } from "../../../app/src/server/policy/types";
    24→import {
    25→  evaluateRegoPolicy,
    26→  createEngineCache,
    27→} from "../../../app/src/server/policy/rego-evaluator";
    28→import { buildGateResult } from "../../../app/src/server/policy/policy-gate";
    29→import { enrichBehaviorScores } from "../../../app/src/server/behavior/queries";
    30→
    31→const getRuntime = setupDynamicBehaviorsSuite("authorizer_integration");
    32→
    33→// =============================================================================
    34→// Walking Skeleton: covered in walking-skeleton.test.ts
    35→// =============================================================================
    36→
    37→// ---------------------------------------------------------------------------
    38→// Helper: Rego source for behavior threshold deny rules
    39→// ---------------------------------------------------------------------------
    40→
    41→/** Rego source that denies when a single behavior score is below a threshold. */
    42→function honestyThresholdRego(threshold: number): string {
    43→  return `package osabio.policy
    44→
    45→deny["Honesty score below threshold"] {
    46→  input.behavior_scores.Honesty < ${threshold}
    47→}
    48→
    49→default allow = true
    50→`;
    51→}
    52→
    53→/** Rego source that denies when Collaboration score is below a threshold. */
    54→function collaborationThresholdRego(threshold: number): string {
    55→  return `package osabio.policy
    56→
    57→deny["Collaboration score below threshold"] {
    58→  input.behavior_scores.Collaboration < ${threshold}
    59→}
    60→
    61→default allow = true
    62→`;
    63→}
    64→
    65→/** Rego source that denies when Honesty OR Evidence_Based is below threshold. */
    66→function multiScoreThresholdRego(
    67→  honestyThreshold: number,
    68→  evidenceThreshold: number,
    69→): string {
    70→  return `package osabio.policy
    71→
    72→deny["Honesty score below threshold"] {
    73→  input.behavior_scores.Honesty < ${honestyThreshold}
    74→}
    75→
    76→deny["Evidence_Based score below threshold"] {
    77→  input.behavior_scores.Evidence_Based < ${evidenceThreshold}
    78→}
    79→
    80→default allow = true
    81→`;
    82→}
    83→
    84→// ---------------------------------------------------------------------------
    85→// Helper: evaluate Rego and build gate result
    86→// ---------------------------------------------------------------------------
    87→async function evaluateAndBuildGateResult(
    88→  regoSource: string,
    89→  policyId: string,
