   102→      denyMessages: regoResult.messages,
   103→      evidenceRequirement: regoResult.evidence_requirement,
   104→      warnings: [],
   105→    }],
   106→    denied,
   107→    [],
   108→  );
   109→
   110→  return { gateResult, regoResult };
   111→}
