     1→/**
     2→ * Acceptance test: BM25 fulltext indexes for learning and policy tables.
     3→ *
     4→ * Verifies that migration 0062 adds BM25 fulltext indexes on:
     5→ *   - learning.text
     6→ *   - policy.description
     7→ *
     8→ * These indexes are required by all Phase 1 steps of the remove-embeddings feature,
     9→ * enabling fulltext search to replace vector/embedding-based search.
    10→ */
    11→import { describe, test, expect, beforeAll, afterAll } from "bun:test";
    12→import { readFileSync } from "node:fs";
    13→import { join } from "node:path";
    14→import { Surreal } from "surrealdb";
    15→import { applyTestSchema } from "../acceptance-test-kit";
    16→
    17→const surrealUrl = process.env.SURREAL_URL ?? "ws://127.0.0.1:8000/rpc";
    18→const surrealUsername = process.env.SURREAL_USERNAME ?? "root";
    19→const surrealPassword = process.env.SURREAL_PASSWORD ?? "root";
    20→
    21→describe("BM25 fulltext indexes migration (0062)", () => {
    22→  let surreal: Surreal;
    23→  const namespace = `bm25_idx_${Date.now()}_${Math.floor(Math.random() * 100000)}`;
    24→  const database = `bm25_test_${Math.floor(Math.random() * 100000)}`;
    25→
    26→  beforeAll(async () => {
    27→    surreal = new Surreal();
    28→    await surreal.connect(surrealUrl);
    29→    await surreal.signin({ username: surrealUsername, password: surrealPassword });
    30→    await surreal.query(`DEFINE NAMESPACE ${namespace};`);
    31→    await surreal.use({ namespace });
    32→    await surreal.query(`DEFINE DATABASE ${database};`);
    33→    await surreal.use({ namespace, database });
    34→
    35→    // Apply base schema
    36→    await applyTestSchema(surreal);
    37→
    38→    // Apply migration 0002 (defines entity_search analyzer + existing fulltext indexes)
    39→    const migration0002 = readFileSync(
    40→      join(process.cwd(), "schema", "migrations", "0002_fulltext_search_indexes.surql"),
    41→      "utf8",
    42→    );
    43→    await surreal.query(migration0002);
    44→
    45→    // Apply migration 0062 (new learning + policy fulltext indexes)
