     1→/**
     2→ * Regorus WASM loader and Rego compilation interface.
     3→ *
     4→ * WASM loading strategy:
     5→ * - Synchronous CJS require() via wasm-bindgen nodejs target
     6→ * - Module-level promise for idempotent lazy init (safe for concurrent calls)
     7→ * - Fail-closed: WASM load failure throws; callers catch to return deny
     8→ */
     9→
    10→import type { IntentEvaluationContext } from "./types";
    11→
    12→export type CompileError = {
    13→  line: number;
    14→  column: number;
    15→  message: string;
    16→};
    17→
    18→export type CompileResult =
    19→  | { success: true }
    20→  | { success: false; errors: CompileError[] };
    21→
    22→export type RegoEvaluationResult = {
    23→  decision: "allow" | "deny";
    24→  messages: string[];
    25→  evidence_requirement?: { min_count: number; required_types?: string[] };
    26→};
    27→
    28→// ---------------------------------------------------------------------------
    29→// WASM module type (subset of Regorus JS bindings)
    30→// ---------------------------------------------------------------------------
    31→
    32→type RegorusModule = {
    33→  Engine: new () => RegorusEngine;
    34→};
    35→
    36→type RegorusEngine = {
    37→  addPolicy(path: string, rego: string): string;
    38→  setInputJson(input: string): void;
    39→  evalQuery(query: string): string;
    40→  getPackages(): string[];
    41→  free(): void;
    42→};
    43→
    44→// ---------------------------------------------------------------------------
    45→// evalQuery result shape
    46→// ---------------------------------------------------------------------------
    47→
    48→type EvalQueryResult = {
    49→  result?: Array<{
    50→    expressions: Array<{
    51→      value: unknown;
    52→    }>;
    53→  }>;
    54→};
    55→
    56→// ---------------------------------------------------------------------------
    57→// Module-level idempotent WASM init promise
    58→// Prohibited: module-level mutable singletons (AGENTS.md)
    59→// Allowed: module-level promise is idempotent — concurrent calls share the
    60→// same promise and all await the same result.
    61→// ---------------------------------------------------------------------------
    62→
    63→const regorusModulePromise: Promise<RegorusModule> = (async () => {
    64→  // require() is synchronous; wrapped in promise for uniform async interface
    65→  // eslint-disable-next-line @typescript-eslint/no-require-imports
    66→  const mod = require("../../../../vendor/regorus-wasm/regorusjs") as RegorusModule;
    67→  if (typeof mod.Engine !== "function") {
    68→    throw new Error("Regorus WASM failed to load: Engine class not found");
    69→  }
    70→  return mod;
    71→})();
    72→
    73→// ---------------------------------------------------------------------------
    74→// Error parsing
    75→// ---------------------------------------------------------------------------
    76→
    77→/**
    78→ * Parse the Regorus error string format into structured CompileError objects.
    79→ *
    80→ * Format example:
    81→ *   \n--> test.rego:2:18\n  |\n2 | default allow := !!!\n  |  ^\nerror: invalid character
    82→ *
    83→ * The location header pattern: `--> <file>:<line>:<column>`
    84→ * The error message follows on the last line: `error: <message>`
    85→ */
    86→const parseRegorusErrorString = (errorString: string): CompileError[] => {
    87→  const lines = errorString.split("\n");
    88→  const errors: CompileError[] = [];
    89→
    90→  let currentLine: number | undefined;
    91→  let currentColumn: number | undefined;
    92→
    93→  for (const line of lines) {
    94→    const locationMatch = line.match(/^-->\s+\S+:(\d+):(\d+)\s*$/);
    95→    if (locationMatch) {
    96→      currentLine = parseInt(locationMatch[1], 10);
    97→      currentColumn = parseInt(locationMatch[2], 10);
    98→      continue;
    99→    }
   100→
   101→    const errorMessageMatch = line.match(/^error:\s+(.+)$/);
   102→    if (errorMessageMatch) {
   103→      errors.push({
   104→        line: currentLine ?? 0,
   105→        column: currentColumn ?? 0,
   106→        message: errorMessageMatch[1].trim(),
   107→      });
   108→      currentLine = undefined;
   109→      currentColumn = undefined;
   110→    }
   111→  }
   112→
   113→  if (errors.length === 0 && errorString.trim().length > 0) {
   114→    // Fallback: return the raw error as a single entry without location
   115→    errors.push({ line: 0, column: 0, message: errorString.trim() });
   116→  }
   117→
   118→  return errors;
   119→};
   120→
   121→// ---------------------------------------------------------------------------
   122→// Package name constant
   123→// ---------------------------------------------------------------------------
   124→
   125→/**
   126→ * The Rego package name that all Osabio policies must declare.
   127→ * Used in both compilation validation and runtime package checking.
   128→ */
   129→export const POLICY_PACKAGE_NAME = "osabio.policy";
   130→
   131→/** Full data path prefix used when querying Regorus engine results. */
   132→const POLICY_DATA_PATH = `data.${POLICY_PACKAGE_NAME}`;
   133→
   134→// ---------------------------------------------------------------------------
   135→// evalQuery helpers
   136→// ---------------------------------------------------------------------------
   137→
   138→const extractQueryValue = (queryResultJson: string): unknown => {
   139→  const parsed = JSON.parse(queryResultJson) as EvalQueryResult;
   140→  if (
   141→    !parsed.result ||
   142→    parsed.result.length === 0 ||
   143→    !parsed.result[0].expressions ||
   144→    parsed.result[0].expressions.length === 0
   145→  ) {
   146→    return undefined;
   147→  }
   148→  return parsed.result[0].expressions[0].value;
   149→};
   150→
   151→const extractAllowValue = (engine: RegorusEngine): boolean => {
   152→  const raw = engine.evalQuery(`${POLICY_DATA_PATH}.allow`);
   153→  const value = extractQueryValue(raw);
   154→  return value === true;
   155→};
   156→
   157→const extractDenyMessages = (engine: RegorusEngine): string[] => {
   158→  const raw = engine.evalQuery(`${POLICY_DATA_PATH}.deny`);
   159→  const value = extractQueryValue(raw);
   160→  if (!Array.isArray(value)) {
   161→    return [];
   162→  }
   163→  return value.filter((msg): msg is string => typeof msg === "string");
   164→};
   165→
   166→const extractEvidenceRequirement = (
   167→  engine: RegorusEngine,
   168→): RegoEvaluationResult["evidence_requirement"] => {
   169→  const raw = engine.evalQuery(`${POLICY_DATA_PATH}.evidence_requirement`);
   170→  const value = extractQueryValue(raw);
   171→
   172→  if (value === undefined || value === null || typeof value !== "object") {
   173→    return undefined;
   174→  }
   175→
   176→  const candidate = value as Record<string, unknown>;
   177→
   178→  if (typeof candidate.min_count !== "number") {
   179→    console.warn(
   180→      "[rego-evaluator] evidence_requirement.min_count is not a number — treating as no requirement",
   181→      candidate,
   182→    );
   183→    return undefined;
   184→  }
   185→
   186→  const requiredTypes =
   187→    Array.isArray(candidate.required_types) &&
   188→    candidate.required_types.every((t) => typeof t === "string")
   189→      ? (candidate.required_types as string[])
   190→      : undefined;
   191→
   192→  if (
   193→    candidate.required_types !== undefined &&
   194→    requiredTypes === undefined
   195→  ) {
   196→    console.warn(
   197→      "[rego-evaluator] evidence_requirement.required_types contains non-string entries — ignoring field",
   198→      candidate.required_types,
   199→    );
   200→  }
   201→
   202→  return { min_count: candidate.min_count, required_types: requiredTypes };
   203→};
   204→
   205→// ---------------------------------------------------------------------------
   206→// Decision logic (fail-closed)
   207→// ---------------------------------------------------------------------------
   208→
   209→const buildDecision = (
   210→  allowValue: boolean,
   211→  denyMessages: string[],
   212→  evidenceRequirement: RegoEvaluationResult["evidence_requirement"],
   213→): RegoEvaluationResult => {
   214→  if (denyMessages.length > 0) {
   215→    return { decision: "deny", messages: denyMessages };
   216→  }
   217→  if (allowValue) {
   218→    return {
   219→      decision: "allow",
   220→      messages: [],
   221→      evidence_requirement: evidenceRequirement,
   222→    };
   223→  }
   224→  // Fail-closed: neither allow=true nor deny messages
   225→  return { decision: "deny", messages: ["policy produced no decision"] };
   226→};
   227→
   228→// ---------------------------------------------------------------------------
   229→// Package validation
   230→// ---------------------------------------------------------------------------
   231→
   232→const validatePackage = (engine: RegorusEngine): void => {
   233→  const packages = engine.getPackages();
   234→  if (!packages.includes(POLICY_DATA_PATH)) {
   235→    throw new Error(`policy must declare package ${POLICY_PACKAGE_NAME}`);
   236→  }
   237→};
   238→
   239→// ---------------------------------------------------------------------------
   240→// Engine cache factory
   241→// ---------------------------------------------------------------------------
   242→
   243→/**
   244→ * Create a new engine cache.
   245→ *
   246→ * The cache is keyed by "${policyId}:${version}" and stores pre-loaded Engine
   247→ * instances. Pass the cache as a parameter to evaluateRegoPolicy — this avoids
   248→ * module-level mutable state (AGENTS.md).
   249→ */
   250→export const createEngineCache = (): Map<string, RegorusEngine> =>
   251→  new Map<string, RegorusEngine>();
   252→
   253→// ---------------------------------------------------------------------------
   254→// Public API
   255→// ---------------------------------------------------------------------------
   256→
   257→/**
