  if (options.outputSchema) {
    content.output_schema = options.outputSchema;
  }

  if (options.provider) {
    content.provider = new RecordId("credential_provider", options.provider);
  }

  await surreal.query(`CREATE $tool CONTENT $content;`, {
    tool: toolRecord,
    content,
  });

  return toolId;
}

